test_suite:
test('starts at step 0 with first value', () => {
  const { result } = renderHook(() =>
    useAnimationSequence([{ duration: 500, value: 10 }, { duration: 300, value: 20 }])
  );
  expect(result.current.currentStep).toBe(0);
  expect(result.current.value).toBe(10);
});

test('start begins animation and does not throw', () => {
  const { result } = renderHook(() =>
    useAnimationSequence([{ duration: 100, value: 5 }])
  );
  expect(() => act(() => result.current.start())).not.toThrow();
});

test('pause does not throw and can be called anytime', () => {
  const { result } = renderHook(() =>
    useAnimationSequence([{ duration: 200, value: 1 }])
  );
  expect(() => act(() => result.current.pause())).not.toThrow();
  act(() => result.current.start());
  expect(() => act(() => result.current.pause())).not.toThrow();
});

test('reset returns to step 0 and first value', () => {
  const { result } = renderHook(() =>
    useAnimationSequence([{ duration: 100, value: 42 }, { duration: 100, value: 99 }])
  );
  act(() => result.current.start());
  act(() => result.current.reset());
  expect(result.current.currentStep).toBe(0);
  expect(result.current.value).toBe(42);
});

// __hidden__
test('empty steps array initializes without error', () => {
  const { result } = renderHook(() => useAnimationSequence([]));
  expect(result.current.currentStep).toBe(0);
  expect(result.current.value).toBeUndefined();
});

solution:
import { useState, useRef, useCallback, useEffect } from 'react';

type AnimStep = { duration: number; value: number };

export function useAnimationSequence(steps: AnimStep[]) {
  const [currentStep, setCurrentStep] = useState(0);
  const [value, setValue] = useState(steps[0]?.value);
  const rafRef = useRef<number | null>(null);
  const startTimeRef = useRef<number | null>(null);
  const pausedRef = useRef(false);
  const stepRef = useRef(0);

  const runStep = useCallback((stepIndex: number) => {
    if (stepIndex >= steps.length) return;
    const step = steps[stepIndex];
    setValue(step.value);
    setCurrentStep(stepIndex);
    stepRef.current = stepIndex;
    startTimeRef.current = null;

    const tick = (now: number) => {
      if (pausedRef.current) return;
      if (!startTimeRef.current) startTimeRef.current = now;
      const elapsed = now - startTimeRef.current;
      if (elapsed >= step.duration) {
        runStep(stepIndex + 1);
      } else {
        rafRef.current = requestAnimationFrame(tick);
      }
    };
    rafRef.current = requestAnimationFrame(tick);
  }, [steps]);

  const start = useCallback(() => {
    pausedRef.current = false;
    runStep(0);
  }, [runStep]);

  const pause = useCallback(() => {
    pausedRef.current = true;
    if (rafRef.current) cancelAnimationFrame(rafRef.current);
  }, []);

  const reset = useCallback(() => {
    pausedRef.current = true;
    if (rafRef.current) cancelAnimationFrame(rafRef.current);
    setCurrentStep(0);
    setValue(steps[0]?.value);
    stepRef.current = 0;
    startTimeRef.current = null;
  }, [steps]);

  useEffect(() => () => { if (rafRef.current) cancelAnimationFrame(rafRef.current); }, []);

  return { currentStep, value, start, pause, reset };
}
